use kelpmux::native::{lifecycle::{Settings, workspace_path}, protocol::*};
use std::{fs, path::PathBuf, process::{Command, Output}, sync::atomic::{AtomicU64,Ordering}, thread, time::{Duration,Instant}};
static NEXT: AtomicU64=AtomicU64::new(0);
struct Fixture {root:PathBuf,state:PathBuf,socket:PathBuf}
impl Fixture {
    fn new()->Self {let root=std::env::temp_dir().join(format!("kelpmux-lifecycle-{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)));fs::create_dir(&root).unwrap();let state=root.join("state");let socket=state.join("control.sock"); Self{root,state,socket}}
    fn cmd(&self,verb:&str,extra:&[&str])->Output {Command::new(env!("CARGO_BIN_EXE_kelpmux")).arg(verb).arg("--state-dir").arg(&self.state).arg("--socket").arg(&self.socket).args(extra).current_dir(&self.root).output().unwrap()}
    fn start(&self,extra:&[&str])->Vec<PaneInfo> {let mut args=vec!["--shell","/bin/sh","--cwd"];let cwd=self.root.to_str().unwrap();args.push(cwd);args.extend(extra);let out=self.cmd("start",&args);assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));match serde_json::from_slice(&out.stdout).unwrap(){ServerMessage::State{panes,..}=>panes,_=>panic!("missing status")}}
    fn status(&self)->Vec<PaneInfo> {let out=self.cmd("status",&[]);assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));match serde_json::from_slice(&out.stdout).unwrap(){ServerMessage::State{panes,..}=>panes,_=>panic!("missing status")}}
    fn stop(&self) {let out=self.cmd("stop",&[]);assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let deadline=Instant::now()+Duration::from_secs(5);while self.socket.exists(){assert!(Instant::now()<deadline,"server did not stop");thread::sleep(Duration::from_millis(10));}}
}
impl Drop for Fixture {fn drop(&mut self){if self.socket.exists(){let _=self.cmd("stop",&[]);let deadline=Instant::now()+Duration::from_secs(3);while self.socket.exists()&&Instant::now()<deadline{thread::sleep(Duration::from_millis(10));}}let _=fs::remove_dir_all(&self.root);}}
#[test]
fn background_workspace_survives_starter_exit_is_idempotent_and_stops_cleanly(){let fixture=Fixture::new();let before=fixture.start(&[]);assert_eq!(before.len(),1);let pid: u32=fs::read_to_string(fixture.state.join("server.pid")).unwrap().trim().parse().unwrap();assert!(fs::metadata(format!("/proc/{pid}")).is_ok());assert_eq!(fixture.start(&[])[0].pid,before[0].pid);assert_eq!(fixture.status()[0].pid,before[0].pid);fixture.stop();let deadline=Instant::now()+Duration::from_secs(3);while fs::metadata(format!("/proc/{}",before[0].pid)).is_ok(){assert!(Instant::now()<deadline);thread::sleep(Duration::from_millis(10));}assert!(!fixture.cmd("status",&[]).status.success());}
#[test]
fn named_workspaces_reject_path_traversal_and_preserve_effective_restart_settings(){for name in ["", "../other", "a/b", ".", "a;exit"]{assert!(workspace_path(name).is_err());}assert!(workspace_path("project-123").unwrap().ends_with("project-123"));let fixture=Fixture::new();fixture.start(&[]);let settings=Settings::load(&fixture.state.join("workspace.json")).unwrap();assert_eq!(settings.cwd.as_ref(),Some(&fixture.root));assert_eq!(settings.shell.as_deref(),Some(std::path::Path::new("/bin/sh")));fixture.stop();let out=Command::new(env!("CARGO_BIN_EXE_kelpmux")).arg("start").arg("--state-dir").arg(&fixture.state).arg("--socket").arg(&fixture.socket).current_dir("/").env("SHELL","/does/not/exist").output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));assert_eq!(fixture.status()[0].cwd,fixture.root.to_string_lossy());fixture.stop();}
#[test]
fn configured_nine_pane_startup_and_invalid_config_are_checked(){let fixture=Fixture::new();let config=fixture.root.join("config.json");fs::write(&config,r#"{"grid":[3,3],"ui":{"prefix":1,"read_width":100,"read_height_percent":80,"bindings":{"r":"read"}}}"#).unwrap();let panes=fixture.start(&["--config",config.to_str().unwrap()]);assert_eq!(panes.len(),9);assert_eq!(panes.iter().map(|p|p.id).collect::<std::collections::BTreeSet<_>>().len(),9);fixture.stop();fs::write(&config,r#"{"grid":[3,4]}"#).unwrap();assert!(!fixture.cmd("start",&["--config",config.to_str().unwrap()]).status.success());assert!(!fixture.socket.exists());}
#[test]
fn pid_fifo_cannot_block_background_start_and_symlink_state_is_rejected(){let fixture=Fixture::new();fs::create_dir(&fixture.state).unwrap();let pid=fixture.state.join("server.pid");let path=std::ffi::CString::new(pid.as_os_str().as_encoded_bytes()).unwrap();assert_eq!(unsafe{libc::mkfifo(path.as_ptr(),0o600)},0);let start=Instant::now();fixture.start(&[]);assert!(start.elapsed()<Duration::from_secs(5));assert!(fs::symlink_metadata(pid).unwrap().is_file());fixture.stop();let foreign=fixture.root.join("foreign");fs::create_dir(&foreign).unwrap();let link=fixture.root.join("symlink-state");std::os::unix::fs::symlink(&foreign,&link).unwrap();let out=Command::new(env!("CARGO_BIN_EXE_kelpmux")).arg("start").arg("--state-dir").arg(&link).arg("--shell").arg("/bin/sh").output().unwrap();assert!(!out.status.success());assert!(!foreign.join("workspace.json").exists());}
